  const guess = Date.UTC(year, month0, day);
  const off1 = zurichOffsetMinutes(new Date(guess));
  const first = guess - off1 * 60000;
  const off2 = zurichOffsetMinutes(new Date(first));
  return new Date(guess - off2 * 60000);
}

/**
 * Booking rules: creation, listing, time change, cancellation; delegates slot and overlap checks to BookingRuleChecker, enforces ownership and the atomic insert. Listings exclude cancelled bookings; a day is a calendar day in Europe/Zurich.
 *
 * @trace DSN-007 REQ-002 REQ-003 REQ-004 REQ-007 REQ-010 REQ-011 REQ-012
 */
export class BookingService {
  constructor(private readonly bookingRuleChecker: BookingRuleChecker, private readonly roomRepository: RoomRepository, private readonly bookingRepository: BookingRepository) {}

  /**
   * Creates a booking for an active room after the rule check, inserting atomically.
   */
  async create(roomId: string, start: Date, end: Date, name: string, email: string): Promise<Booking> {
    this.requireText(name, 'Name');
    this.requireText(email, 'Email');
    const room = await this.getRoom(roomId);
    if (!room.active) {
      throw new Error(`Room ${roomId} is deactivated`);
    }
    await this.bookingRuleChecker.check(roomId, start, end, new Date(), null);
    const booking = new Booking('', roomId, start, end, name.trim(), this.normalizeEmail(email), false);
    return this.bookingRepository.saveIfFree(booking);
  }

  /**
   * Lists non-cancelled bookings created with the given email.
   */
  async listByEmail(email: string): Promise<Booking[]> {
    const normalized = this.normalizeEmail(email);
    const bookings = await this.bookingRepository.findByEmail(normalized);
    return bookings.filter((b) => !b.cancelled);
  }

  /**
   * Lists non-cancelled bookings of a room for a Europe/Zurich calendar day given as YYYY-MM-DD.
   */
  async listByRoomAndDay(roomId: string, date: string): Promise<Booking[]> {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
    if (!match) {
      throw new Error(`Invalid date ${date}, expected YYYY-MM-DD`);
    }
    const year = Number(match[1]);
    const month0 = Number(match[2]) - 1;
    const day = Number(match[3]);
    const dayStart = zurichMidnight(year, month0, day);
    const dayEnd = zurichMidnight(year, month0, day + 1);
    const bookings = await this.bookingRepository.findByRoomAndDay(roomId, dayStart, dayEnd);
    return bookings.filter((b) => !b.cancelled);
  }

  /**
   * Changes start and end of an own, not yet started booking, applying the rule check.
   */
  async changeTime(id: string, email: string, start: Date, end: Date): Promise<Booking> {
    const booking = await this.getBooking(id);
    this.assertOwner(booking, email);
    const now = new Date();
    this.assertActive(booking, now);
    await this.bookingRuleChecker.check(booking.roomId, start, end, now, id);
    booking.startTime = start;
    booking.endTime = end;
    return this.bookingRepository.update(booking);
  }

  /**
   * Cancels an own booking that has not yet started.
   */
  async cancelByUser(id: string, email: string): Promise<void> {
    const booking = await this.getBooking(id);
    this.assertOwner(booking, email);
    this.assertActive(booking, new Date());
    booking.cancelled = true;
    await this.bookingRepository.update(booking);
  }

  /**
   * Cancels any booking that has not yet ended, including one in progress.
   */
  async cancelByAdmin(id: string): Promise<void> {
    const booking = await this.getBooking(id);
    const now = new Date();
    if (booking.endTime.getTime() <= now.getTime()) {
      throw new Error(`Booking ${id} has already ended and cannot be cancelled`);
    }
    booking.cancelled = true;
    await this.bookingRepository.update(booking);
  }

  private async getRoom(roomId: string): Promise<Room> {
    const room = await this.roomRepository.findById(roomId);
    if (!room) {
      throw new Error(`Room ${roomId} not found`);
    }
    return room;
  }

  private async getBooking(id: string): Promise<Booking> {
    const booking = await this.bookingRepository.findById(id);
    if (!booking || booking.cancelled) {
      throw new Error(`Booking ${id} not found`);
    }
    return booking;
  }

  private assertOwner(booking: Booking, email: string): void {
    if (this.normalizeEmail(email) !== this.normalizeEmail(booking.creatorEmail)) {
      throw new Error(`Booking ${booking.id} does not belong to this email`);
    }
  }

  private assertActive(booking: Booking, now: Date): void {
    if (booking.startTime.getTime() <= now.getTime()) {
      throw new Error(`Booking ${booking.id} has already started and cannot be changed`);
    }
  }

  private normalizeEmail(email: string): string {
    return email.trim().toLowerCase();
  }

  private requireText(value: string, field: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${field} is required`);
    }
  }
}

import express, { Express, NextFunction, Request, Response } from 'express';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import { RoomRepository } from '../persistence/RoomRepository.js';
import { BookingRepository } from '../persistence/BookingRepository.js';
import { TimeSlotPolicy } from '../domain-services/TimeSlotPolicy.js';
import { AdminAuthService } from '../domain-services/AdminAuthService.js';
import { AvailabilityService } from '../domain-services/AvailabilityService.js';
import { BookingRuleChecker } from '../domain-services/BookingRuleChecker.js';
import { BookingService } from '../domain-services/BookingService.js';
import { RoomService } from '../domain-services/RoomService.js';
import { AdminGuard } from '../api-layer/AdminGuard.js';
import { RoomController } from '../api-layer/RoomController.js';
import { BookingController } from '../api-layer/BookingController.js';
import { AdminController } from '../api-layer/AdminController.js';

function token(req: Request): string {
  return String(req.header('x-admin-token') ?? '');
}

function str(value: unknown): string {
  return value === undefined || value === null ? '' : String(value);
}

export function createApp(db: DatabaseSync = new DatabaseSync(':memory:')): Express {
  const roomRepository = new RoomRepository(db);
  const bookingRepository = new BookingRepository(db);
  const timeSlotPolicy = new TimeSlotPolicy();
  const adminAuthService = new AdminAuthService();
  const availabilityService = new AvailabilityService(roomRepository, bookingRepository);
  const bookingRuleChecker = new BookingRuleChecker(timeSlotPolicy, bookingRepository);
  const bookingService = new BookingService(bookingRuleChecker, roomRepository, bookingRepository);
  const roomService = new RoomService(roomRepository, bookingRepository);
  const adminGuard = new AdminGuard(adminAuthService);
  const roomController = new RoomController(availabilityService, roomService, adminGuard);
  const bookingController = new BookingController(bookingService, adminGuard);
  const adminController = new AdminController(adminAuthService);

  const app = express();
  app.use(express.json());
  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });
  app.use(express.static(fileURLToPath(new URL('../../public', import.meta.url))));

  app.get('/api/rooms/available', async (req, res) => {
    res.json(await roomController.listAvailable(str(req.query.start), str(req.query.end)));
  });
  app.get('/api/admin/rooms', async (req, res) => {
    res.json(await roomController.listAllRooms(token(req)));
  });
  app.post('/api/admin/rooms', async (req, res) => {
    const b = req.body ?? {};
    const room = await roomController.createRoom(token(req), {
      name: b.name,
      capacity: b.capacity,
      floor: b.floor,
      equipment: b.equipment ?? [],
      active: b.active ?? true,
    });
    res.status(201).json(room);
  });
  app.put('/api/admin/rooms/:id', async (req, res) => {
    res.json(await roomController.updateRoom(token(req), String(req.params.id), req.body ?? {}));
  });
  app.delete('/api/admin/rooms/:id', async (req, res) => {
    await roomController.deleteRoom(token(req), String(req.params.id));
    res.json({ ok: true });
  });
  app.put('/api/admin/rooms/:id/active', async (req, res) => {
    res.json(await roomController.setRoomActive(token(req), String(req.params.id), Boolean(req.body?.active)));
  });

  app.post('/api/bookings', async (req, res) => {
    const b = req.body ?? {};
    const booking = await bookingController.createBooking(str(b.roomId), str(b.start), str(b.end), str(b.name), str(b.email));
    res.status(201).json(booking);
  });
  app.get('/api/bookings', async (req, res) => {
    res.json(await bookingController.listMyBookings(str(req.query.email)));
  });
  app.get('/api/rooms/:roomId/schedule', async (req, res) => {
    res.json(await bookingController.getRoomSchedule(String(req.params.roomId), str(req.query.date)));
  });
  app.put('/api/bookings/:id', async (req, res) => {
    const b = req.body ?? {};
    res.json(await bookingController.changeBooking(String(req.params.id), str(b.email), str(b.start), str(b.end)));
  });
  app.delete('/api/bookings/:id', async (req, res) => {
    await bookingController.cancelBooking(String(req.params.id), str(req.query.email));
    res.json({ ok: true });
  });
  app.delete('/api/admin/bookings/:id', async (req, res) => {
    await bookingController.adminCancelBooking(token(req), String(req.params.id));
    res.json({ ok: true });
  });

  app.post('/api/admin/login', async (req, res) => {
    res.json({ token: await adminController.login(str(req.body?.password)) });
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    const message = err instanceof Error ? err.message : String(err);
    res.status(message.endsWith('not found') ? 404 : 400).json({ error: message });
  });
  return app;
}

